mapper.select:
del_flag = '0'
and ( title_cn ILIKE CONCAT('%', #{searchQuery}, '%') or title_vn ILIKE CONCAT('%', #{searchQuery}, '%') or title_en ILIKE CONCAT('%', #{searchQuery}, '%') or organizer ILIKE CONCAT('%', #{searchQuery}, '%') or industry ILIKE CONCAT('%', #{searchQuery}, '%') or venue ILIKE CONCAT('%', #{searchQuery}, '%') or highlights ILIKE CONCAT('%', #{searchQuery}, '%') or target_audience ILIKE CONCAT('%', #{searchQuery}, '%') )
and event_type = #{eventType}
and status = #{status}
and province ILIKE CONCAT('%', #{province}, '%')
order by case when start_date >= to_char(current_date, 'YYYY-MM-DD') then 0 else 1 end, case when start_date >= to_char(current_date, 'YYYY-MM-DD') then start_date end asc nulls last, case when start_date < to_char(current_date, 'YYYY-MM-DD') then start_date end desc nulls last, title_cn asc
